import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import {packModuleUpload, readPackUploadFile} from './lib/dealer-pack-cloudflare.mjs';

// Native names from the authenticated Wadishee artifact used by run 39445726986.
// The fixture uses harmless generated bytes, keeping the original filename shape.
const nativeNames = [
  'server/app/variant-4/_next/static/framework~index-vjG1Rn5X.js',
  'server/app/variant-4/_next/static/framework~index~page~page~page~page~page~page~page~page~page~page~page~page~page~page~page~~enan11ym-Cf9J3QM3.js',
  'server/app/variant-4/_next/static/framework~index~page~page~page~page~page~page~page~page~page~page~page~page~page~page~page~~i1nr1ugk-g0PuWy_u.js',
  'server/app/variant-4/_next/static/framework~index~page~page~page~page~page~page~page~page~page~page~page~page~page~page~page~~lcdij53a-Nf6jINtu.js',
  'server/mobile/variant-5/_next/static/framework~index-Czj21EDk.js',
  'server/mobile/variant-5/_next/static/framework~index~page~page~page~page~page~page~page~error~page~layout~page~page~page~page~no~eg2jmngh-Cf9J3QM3.js',
  'server/mobile/variant-5/_next/static/framework~index~page~page~page~page~page~page~page~error~page~layout~page~page~page~page~no~lbmchns2-D4nyFxnq.js',
  'server/mobile/variant-5/_next/static/framework~index~page~page~page~page~page~page~page~page~layout~page~page~page~page~page~pag~ccp20eez-xfFYgWrD.js',
  'server/modern/variant-2/_next/static/framework~index-Ccz3Vysy.js',
  'server/modern/variant-2/_next/static/framework~index~page~loading~page~error~page~page~page~layout~loading~page~loading~loading~~n033zcn0-C2zI3FYo.js',
  'server/modern/variant-2/_next/static/framework~index~page~loading~page~page~page~page~layout~loading~page~loading~loading~page~l~ipjmvmlk-CFlrFGBY.js',
  'server/modern/variant-2/_next/static/framework~index~page~page~page~page~loading~page~error~page~page~page~page~layout~loading~p~bf0zmlvr-CWdRdfEh.js',
  'server/modern/variant-2/_next/static/framework~server.react-server-DH4SCRRd.js',
];
const hash = value => createHash('sha256').update(value).digest('hex');
function temporary(t) {
  const tempRoot = fs.realpathSync(os.tmpdir());
  const directory = fs.mkdtempSync(path.join(tempRoot, 'cars-pack-upload-members-'));
  t.after(() => {
    const resolved = fs.realpathSync(directory);
    assert.ok(resolved.startsWith(tempRoot + path.sep) && path.basename(resolved).startsWith('cars-pack-upload-members-'));
    fs.rmSync(resolved, {recursive: true, force: true});
  });
  return directory;
}
function candidate(t) {
  const directory = temporary(t), bytes = Buffer.from('export const fixture = 1;\n');
  const files = ['server/worker.mjs', ...nativeNames].map(name => {
    const target = path.join(directory, name);
    fs.mkdirSync(path.dirname(target), {recursive: true});
    fs.writeFileSync(target, bytes);
    return {path: name, bytes: bytes.length, sha256: hash(bytes)};
  });
  return {directory, files, config: {name: 'cars-wadishee-used-cars', main: 'server/worker.mjs', assets: {binding: 'ASSETS', run_worker_first: false}, compatibility_flags: ['nodejs_compat']}};
}

test('all thirteen retained native tilde names enter the sealed module upload', t => {
  const bundle = candidate(t);
  const request = {slug: 'wadishee-used-cars', workerName: 'cars-wadishee-used-cars', publicOrigin: 'https://wadishee-used-cars.webpreviews.site', id: 'a'.repeat(64), outputDigest: 'b'.repeat(64)};
  const payload = packModuleUpload(bundle, {request, assets: {completionToken: 'test-only-completion-token'}});
  assert.deepEqual(payload.modules.map(row => row.name), ['server/worker.mjs', ...nativeNames]);
  for (const module of payload.modules) {
    const sealed = bundle.files.find(row => row.path === module.name);
    assert.equal(hash(Buffer.from(module.content_base64, 'base64')), sealed.sha256);
  }
});

test('accepting tilde names still rejects changed bytes and unsafe paths', t => {
  const bundle = candidate(t), row = bundle.files[1];
  fs.writeFileSync(path.join(bundle.directory, row.path), 'export const fixture = 2;\n');
  assert.throws(() => readPackUploadFile(bundle, row), /sealed inventory/);
  for (const name of ['server/../private~module.js', 'server/app/../../private~module.js', 'server/app\\..\\private~module.js', 'server/%2e%2e/private~module.js', '/server/private~module.js']) {
    assert.throws(() => readPackUploadFile(bundle, {...row, path: name}), /Unsafe upload member/);
  }
});

test('a valid tilde name cannot escape through a directory junction or symlink', t => {
  const bundle = candidate(t), outside = temporary(t), bytes = Buffer.from('outside');
  fs.writeFileSync(path.join(outside, 'framework~escape.js'), bytes);
  fs.symlinkSync(outside, path.join(bundle.directory, 'server', 'escape'), process.platform === 'win32' ? 'junction' : 'dir');
  assert.throws(() => readPackUploadFile(bundle, {path: 'server/escape/framework~escape.js', bytes: bytes.length, sha256: hash(bytes)}), /symlinked ancestor/);
});
